void NavigationRequest::BeginNavigation() {
  aux_migration::ScopedNavigationAdmission aux_admission(this, true);
  if (!aux_admission.admitted()) {
    if (frame_tree_node_->navigation_request() == this) {
      net_error_ = net::ERR_ABORTED;
      frame_tree_node_->ResetNavigationRequest(
          NavigationDiscardReason::kInternalCancellation);
      return;  // The cancellation deleted this request.
    }
    // A non-FrameTreeNode-owned route cannot be deleted through
    // that owner. Preserve its original cleanup and report the gap.
    aux_migration::ObserveUnsupportedNavigationCancellation();
  }

void NavigationRequest::BeginNavigationImpl() {
  aux_migration::ScopedNavigationAdmission aux_admission(this, false);
  if (!aux_admission.admitted()) {
    if (frame_tree_node_->navigation_request() == this) {
      net_error_ = net::ERR_ABORTED;
      frame_tree_node_->ResetNavigationRequest(
          NavigationDiscardReason::kInternalCancellation);
      return;  // The cancellation deleted this request.
    }
    // A non-FrameTreeNode-owned route cannot be deleted through
    // that owner. Preserve its original cleanup and report the gap.
    aux_migration::ObserveUnsupportedNavigationCancellation();
  }

